package processor

import (
	"encoding/hex"
	"errors"
	"fmt"
	"net"
	"net/http"
	"reflect"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/free5gc/nas"
	"github.com/free5gc/nas/nasMessage"
	"github.com/free5gc/openapi"
	"github.com/free5gc/openapi/models"
	"github.com/free5gc/openapi/udm/SubscriberDataManagement"
	"github.com/free5gc/pfcp/pfcpType"
	smf_context "github.com/free5gc/smf/internal/context"
	"github.com/free5gc/smf/internal/logger"
	smf_errors "github.com/free5gc/smf/pkg/errors"
	"github.com/free5gc/smf/pkg/factory"
	"github.com/free5gc/util/metrics/sbi"
)

func (p *Processor) HandlePDUSessionSMContextCreate(
	c *gin.Context,
	request models.PostSmContextsRequest,
	isDone <-chan struct{},
) {
	// GSM State
	// PDU Session Establishment Accept/Reject
	var response models.PostSmContextsResponse201
	response.JsonData = new(models.SmfPduSessionSmContextCreatedData)
	logger.PduSessLog.Infoln("In HandlePDUSessionSMContextCreate")

	// Check has PDU Session Establishment Request
	m := nas.NewMessage()
	if err := m.GsmMessageDecode(&request.BinaryDataN1SmMessage); err != nil ||
		m.GsmHeader.GetMessageType() != nas.MsgTypePDUSessionEstablishmentRequest {
		logger.PduSessLog.Warnln("GsmMessageDecode Error: ", err)
		postSmContextsError := models.PostSmContextsError{
			JsonData: &models.SmContextCreateError{
				Error: &smf_errors.N1SmError,
			},
		}
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, postSmContextsError.JsonData.Error.Cause)
		c.JSON(http.StatusForbidden, postSmContextsError)
		return
	}

	createData := request.JsonData
	// Check duplicate SM Context
	if dup_smCtx := smf_context.GetSMContextById(createData.Supi, createData.PduSessionId); dup_smCtx != nil {
		p.HandlePDUSessionSMContextLocalRelease(dup_smCtx, createData)
	}

	smContext := smf_context.NewSMContext(createData.Supi, createData.PduSessionId)
	smContext.SetState(smf_context.ActivePending)
	smContext.SmfPduSessionSmContextCreateData = createData
	smContext.SmStatusNotifyUri = createData.SmContextStatusUri

	smContext.SMLock.Lock()
	needUnlock := true
	defer func() {
		if needUnlock {
			smContext.SMLock.Unlock()
		}
	}()

	upi := smf_context.GetUserPlaneInformation()
	upi.Mu.RLock()
	defer upi.Mu.RUnlock()

	// DNN Information from config
	smContext.DNNInfo = smf_context.RetrieveDnnInformation(smContext.SNssai, smContext.Dnn)
	if smContext.DNNInfo == nil {
		logger.PduSessLog.Errorf("S-NSSAI[sst: %d, sd: %s] DNN[%s] not matched DNN Config",
			smContext.SNssai.Sst, smContext.SNssai.Sd, smContext.Dnn)
	}
	smContext.Log.Debugf("S-NSSAI[sst: %d, sd: %s] DNN[%s]",
		smContext.SNssai.Sst, smContext.SNssai.Sd, smContext.Dnn)

	// Query UDM
	if problemDetails, err := p.Consumer().SendNFDiscoveryUDM(); err != nil {
		smContext.Log.Warnf("Send NF Discovery Serving UDM Error[%v]", err)
	} else if problemDetails != nil {
		smContext.Log.Warnf("Send NF Discovery Serving UDM Problem[%+v]", problemDetails)
	} else {
		smContext.Log.Infoln("Send NF Discovery Serving UDM Successfully")
	}

	smPlmnID := createData.Guami.PlmnId

	smDataParams := &SubscriberDataManagement.GetSmDataRequest{
		Dnn: &createData.Dnn,
		PlmnId: &models.PlmnId{
			Mcc: smPlmnID.Mcc,
			Mnc: smPlmnID.Mnc,
		},
		SingleNssai: smContext.SNssai,
	}

	ctx, _, oauthErr := smf_context.GetSelf().GetTokenCtx(models.ServiceName_NUDM_SDM, models.NrfNfManagementNfType_UDM)
	if oauthErr != nil {
		smContext.Log.Errorf("Get Token Context Error[%v]", oauthErr)
		return
	}

	if sessSubData, err := p.Consumer().
		GetSmData(ctx, smContext.Supi, smDataParams); err != nil {
		smContext.Log.Errorln("Get SessionManagementSubscriptionData error:", err)
	} else {
		if len(sessSubData) > 0 {
			smContext.DnnConfiguration = sessSubData[0].DnnConfigurations[smContext.Dnn]
			// UP Security info present in session management subscription data
			if smContext.DnnConfiguration.UpSecurity != nil {
				smContext.UpSecurity = smContext.DnnConfiguration.UpSecurity
			}

smContext.TrafficControlDatas = make(map[string]*TrafficControlData)
smContext.QosDatas = make(map[string]*models.QosData)
smContext.UpPathChgEarlyNotification = make(map[string]*EventExposureNotification)
smContext.UpPathChgLateNotification = make(map[string]*EventExposureNotification)
smContext.DataPathToBeRemoved = make(map[int64]*DataPath)

smContext.ProtocolConfigurationOptions = &ProtocolConfigurationOptions{}

smContext.BPManager = NewBPManager(id)
smContext.Tunnel = NewUPTunnel()
smContext.DCTunnel = NewUPTunnel()

smContext.QoSRuleIDGenerator = idgenerator.NewGenerator(1, 255)
if defRuleID, err := smContext.QoSRuleIDGenerator.Allocate(); err != nil {
	logger.CtxLog.Warnln("Create Default QoS rule error ", err)
} else {
	smContext.defRuleID = uint8(defRuleID)
}

smContext.PacketFilterIDGenerator = idgenerator.NewGenerator(1, 255)
smContext.QFIGenerator = idgenerator.NewGenerator(2, 63) // 1 always reserve for default Qos
smContext.PCCRuleIDToQoSRuleID = make(map[string]uint8)
smContext.PacketFilterIDToNASPFID = make(map[string]uint8)
smContext.qosDataToQFI = make(map[string]uint8)
smContext.AMBRQerMap = make(map[uuid.UUID]uint32)
smContext.QerUpfMap = make(map[string]uint32)
smContext.AdditonalQosFlows = make(map[uint8]*QoSFlow)
smContext.UrrIDGenerator = idgenerator.NewGenerator(1, math.MaxUint32)
smContext.UrrIdMap = make(map[UrrType]uint32)
smContext.GenerateUrrId()
smContext.UrrUpfMap = make(map[string]*URR)

smContext.ChargingInfo = make(map[uint32]*ChargingInfo)
smContext.ChargingID = GenerateChargingID()

if factory.SmfConfig != nil &&
	factory.SmfConfig.Configuration != nil {
	smContext.UrrReportTime = time.Duration(factory.SmfConfig.Configuration.UrrPeriod) * time.Second
	smContext.UrrReportThreshold = factory.SmfConfig.Configuration.UrrThreshold
	logger.CtxLog.Infof("UrrPeriod: %v", smContext.UrrReportTime)
	logger.CtxLog.Infof("UrrThreshold: %d", smContext.UrrReportThreshold)
	if factory.SmfConfig.Configuration.RequestedUnit != 0 {
		smContext.RequestedUnit = factory.SmfConfig.Configuration.RequestedUnit
	} else {
		smContext.RequestedUnit = 1000
	}
}

var err error
smContext.LocalDLTeid, err = GenerateTEID()
if err != nil {
	return nil
}

smContext.LocalULTeid, err = GenerateTEID()
if err != nil {
	return nil
}

smContext.LocalULTeidForSplitPDUSession, err = GenerateTEID()
if err != nil {

		},
		{
			Name:    "TransferMoData",
			Method:  http.MethodPost,
			Pattern: "/pdu-sessions/:pduSessionRef/transfer-mo-data",
			APIFunc: s.HTTPTransferMoData,
		},
	}
}

// HTTPPostSmContexts - Create SM Context
func (s *Server) HTTPPostSmContexts(c *gin.Context) {
	logger.PduSessLog.Info("Receive Create SM Context Request")
	var request models.PostSmContextsRequest

	request.JsonData = new(models.SmfPduSessionSmContextCreateData)

	contentType := strings.Split(c.GetHeader("Content-Type"), ";")
	var err error
	switch contentType[0] {
	case APPLICATION_JSON:
		err = c.ShouldBindJSON(request.JsonData)
	case MULTIPART_RELATED:
		err = c.ShouldBindWith(&request, openapi.MultipartRelatedBinding{})
	}

	if err != nil {
		problemDetail := "[Request Body] " + err.Error()
		logger.PduSessLog.Errorln(problemDetail)
		problemDetails := openapi.ProblemDetailsMalformedReqSyntax(problemDetail)
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, http.StatusText(int(problemDetails.Status)))
		c.JSON(int(problemDetails.Status), problemDetails)
		return
	}

	if !validator.IsValidSupi(request.JsonData.Supi) {
		problemDetail := "Invalid SUPI format: " + request.JsonData.Supi
		logger.PduSessLog.Warnln(problemDetail)

		problemDetails := openapi.ProblemDetailsMalformedReqSyntax(problemDetail)
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, http.StatusText(int(problemDetails.Status)))
		c.JSON(int(problemDetails.Status), problemDetails)
		return
	}

	isDone := c.Done()
	s.Processor().HandlePDUSessionSMContextCreate(c, request, isDone)
}

// HTTPUpdateSmContext - Update SM Context
func (s *Server) HTTPUpdateSmContext(c *gin.Context) {
	logger.PduSessLog.Info("Receive Update SM Context Request")
	var request models.UpdateSmContextRequest
	request.JsonData = new(models.SmfPduSessionSmContextUpdateData)

